window.ATLAS_DATA={"entries": [{"id": "song", "name": "Song China", "region": "East Asia", "lon": 120.2, "lat": 30.3, "periods": ["before", "core"], "dates": "960–1279", "image": "assets/slides/d1-image2.png", "refs": ["d1:3", "d1:4", "d1:7", "d1:8", "d1:9", "d1:10"], "summary": "Bureaucracy, agricultural innovation, and a commercial economy.", "facts": ["An emperor and centralized bureaucracy governed the empire. The expanded civil service examinations selected educated scholar-officials.", "The Mandate of Heaven justified imperial authority through effective rule. Confucianism emphasized hierarchy, filial piety, and social harmony.", "Neo-Confucianism incorporated influences from Buddhism and Daoism. Elite foot binding reinforced patriarchal hierarchies.", "Champa rice from Vietnam enabled multiple harvests. Irrigation improvements increased food production and supported population growth and urbanization.", "Paper money eased transactions. The Grand Canal moved grain and goods between northern and southern China. Hangzhou and Kaifeng grew as commercial cities.", "Junks supported maritime trade. Silk, porcelain, and tea traveled through long-distance networks; paper and gunpowder spread westward.", "Mahayana Buddhism spread in East Asia. Chan blended Buddhist and Daoist traditions and developed into Zen in Japan."], "tea": {"prompt": "Explain one way agricultural change supported Song economic growth.", "topic": "Agricultural innovation supported economic expansion in Song China.", "explain": "Champa rice from Vietnam allowed multiple harvests each year, increasing food supplies.", "analyze": "More food supported a larger population and growing cities, which expanded demand and exchange."}, "traps": ["Civil service examinations concern government recruitment; the Mandate of Heaven concerns legitimacy.", "Champa rice concerns agricultural productivity. Paper money and the Grand Canal concern exchange and transport."], "quiz": {"question": "Which development most directly increased the food supply in Song China?", "options": ["Champa rice and multiple harvests", "Issuing paper money for transactions", "Expanding civil service examinations", "Invoking the Mandate of Heaven"], "explanation": "The slides link Champa rice and improved farming to greater food production, population growth, and urbanization."}, "displayImage": "assets/web/d1-image2.webp", "units": ["units12"]}, {"id": "ming", "name": "Ming China & Zheng He", "region": "East Asia", "lon": 118.8, "lat": 32.1, "periods": ["core", "after"], "dates": "Ming 1368–1644; voyages 1405–1433", "image": "assets/slides/d1-image10.GIF", "refs": ["d1:11", "d7:8"], "summary": "State-funded voyages projected imperial power across the Indian Ocean.", "facts": ["The Ming restored native Chinese rule after the Mongol Yuan dynasty fell in 1368.", "Zheng He led large naval expeditions between 1405 and 1433, traveling as far as East Africa.", "The state funded the voyages to establish diplomatic ties, collect tribute, and project Chinese power.", "The voyages strengthened connections with India, the Middle East, and Africa. The Mongol deck notes that Ming rulers retained some Mongol administrative practices."], "tea": {"prompt": "Explain one difference between Song commercial activity and Zheng He’s voyages.", "topic": "Zheng He’s voyages served state diplomatic goals.", "explain": "The Ming funded expeditions to collect tribute and project power, whereas the slides describe Song trade as driven by private merchants.", "analyze": "Both connected China to wider networks, but the voyages made exchange an instrument of imperial authority."}, "traps": ["Zheng He’s voyages belong to the Ming, after Mongol Yuan rule.", "The slides distinguish Ming diplomatic expeditions from Song commerce driven by private merchants."], "quiz": {"question": "What was a central purpose of Zheng He’s expeditions?", "options": ["Collecting tribute and projecting Ming power", "Selecting scholar-officials through examinations", "Expanding privately organized merchant trade", "Restoring the Mongol Yuan government"], "explanation": "The East Asia deck identifies diplomacy, tribute, and the projection of state power as goals."}, "displayImage": "assets/web/d1-image10.webp", "units": ["units12"]}, {"id": "japan", "name": "Japan", "region": "East Asia", "lon": 135.8, "lat": 35.0, "periods": ["core"], "dates": "1200–1450 study window", "image": "assets/slides/d1-image5.png", "refs": ["d1:6", "d1:7"], "summary": "Chinese cultural influence adapted to decentralized political rule.", "facts": ["Japan adopted elements of Chinese writing, political organization, and cultural practices while preserving local structures.", "The slides describe a feudal system led by the shogun and samurai, with regional lords controlling land and military forces.", "An emperor existed, but political power was decentralized.", "Chan Buddhism spread from China and developed into Zen in Japan."], "tea": {"prompt": "Explain one way Chinese cultural influence coexisted with local political traditions in Japan.", "topic": "Japan adapted Chinese culture without reproducing Song centralization.", "explain": "It adopted elements of Chinese writing and Confucian traditions, while regional lords held land and military power.", "analyze": "Cultural diffusion could occur alongside political decentralization; shared ideas did not require identical governments."}, "traps": ["An emperor’s existence does not by itself establish centralized control.", "Chan is the Chinese tradition discussed in the deck; Zen is its Japanese development."], "quiz": {"question": "Which pairing matches the East Asia slides?", "options": ["Japan: decentralized power under regional lords", "Japan: centralized Song-style bureaucracy", "Japan: political authority held only by the emperor", "Japan: complete rejection of Chinese culture"], "explanation": "The deck contrasts Japanese feudal decentralization with Chinese centralized bureaucracy."}, "displayImage": "assets/web/d1-image5.webp", "units": ["units12"]}, {"id": "korea", "name": "Korea", "region": "East Asia", "lon": 127.0, "lat": 37.6, "periods": ["core"], "dates": "1200–1450 study window", "image": "assets/slides/d1-image4.jpeg", "refs": ["d1:5", "d1:6"], "summary": "A regional example of the adaptation of Chinese traditions.", "facts": ["The East Asia deck names Korea among societies influenced by Chinese political organization, writing, and cultural practices.", "Confucian traditions shaped education and ideas of hierarchy and authority across the region.", "The slides emphasize adaptation and continued local political structures and cultural identities. They provide no separate dynasty-level account for this location."], "tea": {"prompt": "Explain how Korea illustrates the adaptation of Chinese traditions.", "topic": "Korea illustrates the regional adaptation of Chinese culture.", "explain": "The slides identify the adoption of elements of Chinese writing and political culture alongside local identities.", "analyze": "This supports an argument that cultural influence could cross borders without eliminating local differences."}, "traps": ["The slides describe influence and adaptation, rather than identical institutions everywhere.", "Do not apply the Japanese shogun/samurai example to every East Asian society."], "quiz": {"question": "What claim about Korea is supported by these slides?", "options": ["Chinese traditions influenced it alongside continued local identities", "Chinese influence eliminated all local political structures", "The Japanese shogun example described Korean government", "The deck gives a separate detailed Korean dynasty chronology"], "explanation": "Slide 6 explicitly names Korea, Japan, and Vietnam as societies that adapted Chinese traditions."}, "displayImage": "assets/web/d1-image4.webp", "units": ["units12"]}, {"id": "vietnam", "name": "Vietnam", "region": "East Asia", "lon": 105.8, "lat": 21.0, "periods": ["core"], "dates": "1200–1450 study window", "image": "assets/slides/d1-image4.jpeg", "refs": ["d1:5", "d1:6"], "summary": "A regional example of the adaptation of Chinese traditions.", "facts": ["The East Asia deck names Vietnam among societies influenced by Chinese political organization, writing, and cultural practices.", "Confucian traditions shaped education and ideas of hierarchy and authority across the region.", "The slides emphasize adaptation and continued local political structures and cultural identities. They provide no separate dynasty-level account for this location."], "tea": {"prompt": "Explain how Vietnam illustrates the adaptation of Chinese traditions.", "topic": "Vietnam illustrates the regional adaptation of Chinese culture.", "explain": "The slides identify the adoption of elements of Chinese writing and political culture alongside local identities.", "analyze": "This supports an argument that cultural influence could cross borders without eliminating local differences."}, "traps": ["The slides describe influence and adaptation, rather than identical institutions everywhere.", "Do not apply the Japanese shogun/samurai example to every East Asian society."], "quiz": {"question": "What claim about Vietnam is supported by these slides?", "options": ["Chinese traditions influenced it alongside continued local identities", "Chinese influence eliminated all local cultural identities", "Vietnam was the shogun-led example in the deck", "The deck supplies a separate detailed Vietnamese state chronology"], "explanation": "Slide 6 explicitly names Korea, Japan, and Vietnam as societies that adapted Chinese traditions."}, "displayImage": "assets/web/d1-image4.webp", "units": ["units12"]}, {"id": "baghdad", "name": "Baghdad & Dar al-Islam", "region": "Islamic world", "lon": 44.4, "lat": 33.3, "periods": ["before", "core"], "dates": "Abbasids 750–1258; wider network 1200–1450", "image": "assets/slides/d2-image9.png", "refs": ["d2:3", "d2:4", "d2:5", "d2:6", "d2:8", "d2:9", "d2:10", "d7:5"], "summary": "Political fragmentation coexisted with shared religion, scholarship, and trade.", "facts": ["Baghdad was the Abbasid capital and a major center of trade, culture, and learning. Mongols conquered it in 1258.", "The Abbasid political system weakened, but Islamic cultural and trade networks continued across Afro-Eurasia.", "Arabic, Sharia, mosques, and educational institutions connected diverse societies. Conversion could offer access to trade, education, or government positions.", "Sufi missionaries, merchants, migration, and conquest helped Islam spread. Sufis adapted teachings to local cultures.", "The House of Wisdom translated classical texts. Scholars preserved and expanded Greek, Roman, Indian, and Persian knowledge. Al-Khwarizmi contributed to algebra.", "Ibn Battuta’s travels illustrate shared religious traditions and cultural connections across Dar al-Islam.", "The slides describe patriarchal gender roles alongside women’s ability to hold property, inherit wealth, and trade."], "tea": {"prompt": "Explain how Islamic societies remained connected despite political fragmentation.", "topic": "Shared institutions sustained connections across Dar al-Islam.", "explain": "Arabic, Islamic law, and trade networks linked societies even as the Abbasid state weakened and new states emerged.", "analyze": "Cultural and economic integration therefore continued without a single political ruler."}, "traps": ["Dar al-Islam is a broad religious and cultural region; it is not the name of one unified empire in this period.", "The decline of Abbasid political unity did not end Islamic scholarship or exchange."], "quiz": {"question": "What best explains continued connections after Abbasid fragmentation?", "options": ["Shared religion, Arabic, and trade networks", "A unified Abbasid ruler maintained control over every region", "Political fragmentation ended shared Islamic traditions", "Local adaptations prevented all cultural exchange"], "explanation": "The deck repeatedly distinguishes weakened political unity from continued cultural and economic connections."}, "displayImage": "assets/web/d2-image9.webp", "units": ["units12"]}, {"id": "seljuk", "name": "Seljuk Empire", "region": "Islamic world", "lon": 51.7, "lat": 32.7, "periods": ["core"], "dates": "Example in the 1200–1450 lesson", "image": "assets/slides/d2-image3.webp", "refs": ["d2:4", "d2:5"], "summary": "An example used to explain the fragmentation of Abbasid political unity.", "facts": ["The deck locates the Seljuk Empire in Persia and includes it among new Islamic states discussed after Abbasid fragmentation.", "The regional lesson emphasizes continued Islamic traditions alongside adaptation to local conditions.", "This is a brief slide example. The decks do not provide a separate detailed chronology for this state."], "tea": {"prompt": "Explain what the emergence of multiple Islamic states demonstrates.", "topic": "Political authority became divided across the Islamic world.", "explain": "The deck lists the Seljuk Empire in Persia alongside other Islamic states after Abbasid unity declined.", "analyze": "The examples show political fragmentation within a broader connected religious and cultural region."}, "traps": ["Remember the location used in the slides: Seljuk Empire, Persia.", "Use this example for fragmentation; do not infer that Islamic religious connections disappeared."], "quiz": {"question": "Where do the slides locate the Seljuk Empire?", "options": ["Persia", "Egypt", "Northern India", "Mesoamerica"], "explanation": "The fragmentation slide identifies the Seljuk Empire with Persia."}, "displayImage": "assets/web/d2-image3.webp", "units": ["units12"]}, {"id": "mamluk", "name": "Mamluk Sultanate", "region": "Islamic world", "lon": 31.2, "lat": 30.0, "periods": ["core"], "dates": "Example in the 1200–1450 lesson", "image": "assets/slides/d2-image4.jpeg", "refs": ["d2:4", "d2:5"], "summary": "An example used to explain the fragmentation of Abbasid political unity.", "facts": ["The deck locates the Mamluk Sultanate in Egypt and includes it among new Islamic states discussed after Abbasid fragmentation.", "The regional lesson emphasizes continued Islamic traditions alongside adaptation to local conditions.", "This is a brief slide example. The decks do not provide a separate detailed chronology for this state."], "tea": {"prompt": "Explain what the emergence of multiple Islamic states demonstrates.", "topic": "Political authority became divided across the Islamic world.", "explain": "The deck lists the Mamluk Sultanate in Egypt alongside other Islamic states after Abbasid unity declined.", "analyze": "The examples show political fragmentation within a broader connected religious and cultural region."}, "traps": ["Remember the location used in the slides: Mamluk Sultanate, Egypt.", "Use this example for fragmentation; do not infer that Islamic religious connections disappeared."], "quiz": {"question": "Where do the slides locate the Mamluk Sultanate?", "options": ["Egypt", "Persia", "Northern India", "Central Asia"], "explanation": "The fragmentation slide identifies the Mamluk Sultanate with Egypt."}, "displayImage": "assets/web/d2-image4.webp", "units": ["units12"]}, {"id": "delhi", "name": "Delhi Sultanate", "region": "South & Southeast Asia", "lon": 77.2, "lat": 28.6, "periods": ["core"], "dates": "1200–1450 lesson; slide map shows several dates", "image": "assets/slides/d3-image10.png", "refs": ["d2:4", "d2:6", "d3:8", "d3:9"], "summary": "Islamic political rule and cultural interaction in northern India.", "facts": ["The Delhi Sultanate introduced Islamic governance and culture to northern India.", "The Islamic-world deck uses Delhi as an example of Islam spreading through military expansion.", "The South Asia deck highlights syncretism in art, architecture, and social customs.", "Islam coexisted with Hindu and Buddhist traditions across the wider region."], "tea": {"prompt": "Explain one way the spread of Islam shaped northern India.", "topic": "Islamic rule introduced new political and cultural practices in northern India.", "explain": "The Delhi Sultanate introduced Islamic governance and fostered syncretic traditions in architecture and social customs.", "analyze": "Political expansion could encourage cultural interaction rather than simply replace every local tradition."}, "traps": ["Delhi is the northern Indian Islamic example; Vijayanagara is the southern Indian Hindu example.", "Distinguish conquest as one route of diffusion from merchant and Sufi activity on maritime routes."], "quiz": {"question": "Which state introduced Islamic political rule to northern India?", "options": ["Delhi Sultanate", "Vijayanagara Empire", "Khmer Empire", "Majapahit Empire"], "explanation": "Both the Dar al-Islam and South Asia decks identify the Delhi Sultanate with Islamic rule in northern India."}, "displayImage": "assets/web/d3-image10.webp", "units": ["units12"]}, {"id": "silk-roads", "name": "Silk Road cities", "region": "Islamic world", "lon": 67.0, "lat": 39.7, "periods": ["core"], "dates": "1200–1450 network study", "image": "assets/slides/d2-image8.jpeg", "refs": ["d1:10", "d2:7", "d7:6", "d7:7"], "summary": "Samarkand, Kashgar, and Baghdad linked trade and cultural exchange.", "facts": ["The slides name Baghdad, Samarkand, and Kashgar as hubs of commerce and cultural exchange.", "Overland travel costs favored high-value luxury goods, including silk, porcelain, textiles, spices, and precious metals.", "Caravans grouped merchants, animals, and goods for safety. Caravanserai provided food, lodging, protection, and opportunities to exchange news and ideas.", "Mongol rule supported safer travel and relay communications. Trade routes carried religions and technologies as well as disease."], "tea": {"prompt": "Explain one way infrastructure supported long-distance overland trade.", "topic": "Caravanserai supported merchants traveling long desert routes.", "explain": "They offered food, lodging, and protection to traders and their animals.", "analyze": "Reducing travel difficulties helped sustain exchange, while shared stopping places also circulated news and ideas."}, "traps": ["A caravan is a traveling group; a caravanserai is a roadside inn.", "The Silk Roads favored luxury goods. Indian Ocean ships also carried bulk goods."], "quiz": {"question": "What was a caravanserai?", "options": ["A roadside inn for merchants and animals", "A traveling group of merchants and animals", "A relay station providing fresh horses for messengers", "A permanent foreign merchant community in a port"], "explanation": "The Dar al-Islam deck defines caravanserai as roadside inns that supported trade and exchange."}, "displayImage": "assets/web/d2-image8.webp", "units": ["units12"]}, {"id": "vijayanagara", "name": "Vijayanagara", "region": "South & Southeast Asia", "lon": 76.5, "lat": 15.3, "periods": ["core"], "dates": "1200–1450 study window", "image": "assets/slides/d3-image8.png", "refs": ["d3:3", "d3:4", "d3:7", "d3:10"], "summary": "Hindu kingship, temple patronage, and state authority in southern India.", "facts": ["Vijayanagara preserved Hindu traditions while promoting trade and military strength.", "The slides describe a powerful monarchy and bureaucracy. Rulers associated themselves with Hindu gods to claim divine authority.", "Rulers expanded and patronized the Virupaksha Temple to legitimize their rule and promote Hindu unity.", "The regional lesson describes Hinduism’s influence on caste, art, architecture, and religious rituals."], "tea": {"prompt": "Explain one way Vijayanagara rulers used religion to support political authority.", "topic": "Vijayanagara rulers used Hindu temple patronage to legitimize power.", "explain": "They expanded and supported the Virupaksha Temple and associated their rule with Hindu gods.", "analyze": "Religious patronage linked the monarchy to divine authority and promoted unity among supporters."}, "traps": ["Vijayanagara is the southern Indian Hindu example, distinct from the Delhi Sultanate.", "Temple patronage can serve a political purpose as well as a religious one."], "quiz": {"question": "Which example links Hindu temple patronage to political legitimacy?", "options": ["Vijayanagara support for Virupaksha Temple", "Delhi’s introduction of Islamic political rule", "Ming sponsorship of tribute expeditions", "Igbo communal decision-making"], "explanation": "The South Asia deck explicitly connects Virupaksha patronage with the legitimacy of Vijayanagara rulers."}, "displayImage": "assets/web/d3-image8.webp", "units": ["units12"]}, {"id": "khmer", "name": "Khmer & Angkor", "region": "South & Southeast Asia", "lon": 103.9, "lat": 13.4, "periods": ["before", "core"], "dates": "Angkor Wat: early 1100s; continued use in the lesson period", "image": "assets/slides/d3-image7.png", "refs": ["d3:4", "d3:6", "d3:10"], "summary": "Monumental architecture expressed religious and royal authority.", "facts": ["The Khmer example combines Hindu and Buddhist traditions with divine kingship.", "The slides describe Angkor Wat as initially a Hindu temple, built in the early 12th century, that later became a Buddhist site.", "Its scale and carvings demonstrated the king’s divine authority and helped unify the empire."], "tea": {"prompt": "Explain one way monumental architecture supported Khmer political authority.", "topic": "Angkor Wat connected royal authority to religious devotion.", "explain": "The large temple and intricate carvings displayed the Khmer king’s divine authority.", "analyze": "Such monuments could strengthen legitimacy by giving religious authority a visible public form."}, "traps": ["Angkor Wat began as a Hindu temple and later became a Buddhist site.", "A monument used during 1200–1450 need not have been built during 1200–1450."], "quiz": {"question": "Which sequence matches the Angkor Wat slide?", "options": ["Initially Hindu, later Buddhist", "Initially Buddhist, later Hindu", "Built for the first time in the late 1400s", "Originally a mosque tied to maritime conversions"], "explanation": "The architecture slide identifies Angkor Wat’s initial Hindu use and later Buddhist transformation."}, "displayImage": "assets/web/d3-image7.webp", "units": ["units12"]}, {"id": "majapahit", "name": "Majapahit & Java", "region": "South & Southeast Asia", "lon": 112.4, "lat": -7.6, "periods": ["before", "core", "after"], "dates": "Majapahit c. 1293–1527; Borobudur 800s; Demak late 1400s", "image": "assets/slides/d3-image11.png", "refs": ["d3:4", "d3:5", "d3:10"], "summary": "Hindu-Buddhist syncretism and architecture across several periods.", "facts": ["Majapahit rulers drew divine authority from Hindu and Buddhist traditions. The deck uses this as an example of syncretism.", "Borobudur was a Buddhist temple built in the 9th century. The slides identify its continued cultural significance in 1200–1450.", "The Great Mosque of Demak belongs to the late 15th century. The deck highlights its blend of Javanese Hindu-Buddhist and Islamic architectural styles."], "tea": {"prompt": "Explain one example of religious syncretism in Southeast Asia.", "topic": "Majapahit combined Hindu and Buddhist traditions in royal legitimacy.", "explain": "Its rulers claimed divine authority rooted in both religious traditions.", "analyze": "This blending shows how states could adapt multiple religious traditions to support political authority."}, "traps": ["Borobudur’s construction predates 1200; Demak’s mosque belongs after 1450.", "Syncretism means the blending of traditions, not the disappearance of all local culture."], "quiz": {"question": "Which building’s construction is a post-1450 extension in the slides?", "options": ["Great Mosque of Demak", "Borobudur", "Angkor Wat", "The earlier Olmec example"], "explanation": "The slides date Demak’s mosque to the late 15th century. Borobudur and Angkor Wat were built earlier."}, "displayImage": "assets/web/d3-image11.webp", "units": ["units12"]}, {"id": "malacca", "name": "Malacca", "region": "South & Southeast Asia", "lon": 102.2, "lat": 2.2, "periods": ["core"], "dates": "1200–1450 study window", "image": "assets/slides/d3-image13.jpeg", "refs": ["d3:8", "d3:11", "d3:12"], "summary": "A maritime chokepoint made trade a source of political power.", "facts": ["Malacca grew as an Indian Ocean port and a maritime sultanate.", "Control of the Strait of Malacca allowed the state to tax passing ships and regulate trade.", "Merchants used predictable seasonal monsoon winds to time voyages.", "Muslim merchants and Sufi missionaries helped spread Islam through coastal trade networks."], "tea": {"prompt": "Explain one way geography supported the rise of Malacca.", "topic": "Control of a maritime chokepoint supported Malacca’s power.", "explain": "The sultanate controlled the Strait of Malacca and taxed ships passing through it.", "analyze": "Concentrated shipping gave rulers revenue and influence over a major interregional network."}, "traps": ["Malacca’s power depended on a sea strait, rather than trans-Saharan camel routes.", "Monsoons were predictable seasonal winds that merchants used to schedule travel."], "quiz": {"question": "How did Malacca turn its geographic position into state revenue?", "options": ["Taxing ships passing through its strait", "Administering trans-Saharan gold and salt caravans", "Expanding civil service examinations", "Requiring Andean public labor service"], "explanation": "The slides link control of the Strait of Malacca to taxation and trade regulation."}, "displayImage": "assets/web/d3-image13.webp", "units": ["units12"]}, {"id": "calicut", "name": "Calicut & Indian Ocean", "region": "South & Southeast Asia", "lon": 75.8, "lat": 11.3, "periods": ["core"], "dates": "1200–1450 network study", "image": "assets/slides/d3-image12.png", "refs": ["d3:11", "d3:12", "d3:13", "d5:8"], "summary": "Seasonal winds, large cargoes, and merchant communities connected coasts.", "facts": ["Calicut and Malacca developed as port cities linking East Africa, South Asia, Southeast Asia, and the Middle East.", "Ships carried both luxury goods, such as spices and fine textiles, and bulk cargoes, including timber, rice, and cotton cloth.", "Large ships and lower transport costs distinguished maritime trade from expensive overland luxury trade.", "Merchants timed voyages to seasonal monsoon winds. Dhows and junks supported long-distance shipping.", "Trade networks moved crops: bananas westward to Africa, and sugarcane and citrus toward western Afro-Eurasia. The deck connects banana diffusion to food supplies and population growth.", "Permanent merchant communities connected cultural and economic systems. See the Swahili coast for the deck’s detailed diaspora example."], "tea": {"prompt": "Explain one difference between Indian Ocean and Silk Road trade.", "topic": "Indian Ocean shipping could carry substantial bulk cargoes.", "explain": "The slides list timber, rice, and cotton cloth alongside luxury cargoes because ships offered larger capacity and lower costs.", "analyze": "Transport conditions shaped what merchants could profitably exchange, rather than every route carrying the same mix of goods."}, "traps": ["Indian Ocean trade included bulk goods as well as luxuries.", "Diaspora means a settled community away from its homeland, rather than a short trading visit."], "quiz": {"question": "Why could Indian Ocean merchants transport rice and timber economically?", "options": ["Larger ships and lower shipping costs", "Overland camel transport was cheaper for bulk cargoes", "Ocean trade carried only small luxury goods", "Seasonal monsoons prevented predictable travel planning"], "explanation": "The South Asia slides explicitly connect bulk maritime cargoes with ship capacity and lower transport costs."}, "displayImage": "assets/web/d3-image12.webp", "units": ["units12"]}, {"id": "aztec", "name": "Aztec Empire", "region": "Americas", "lon": -99.1, "lat": 19.4, "periods": ["core", "earlymodern"], "dates": "Rise in the 1300s–1400s", "image": "assets/slides/d4-image7.jpeg", "refs": ["d4:6", "d4:7", "d4:10", "d9:10"], "summary": "Tribute and lake agriculture supported an urban empire.", "facts": ["The Triple Alliance linked three city-states, with Tenochtitlán as the dominant capital.", "Indirect rule left local rulers in place while conquered states supplied tribute in goods, food, and captives. Feathers, cacao, and obsidian were valuable tribute goods.", "Tribute generated resentment among conquered peoples, which Spanish conquerors later exploited.", "Tenochtitlán stood on an island. Aqueducts supplied fresh water and causeways connected it to the mainland.", "Chinampas were fertile plots built on shallow lake beds, allowing multiple harvests and supporting a large urban population.", "The slides describe polytheism, divine rulers, and human sacrifice as central to Aztec religious and political life.", "Unit 3 revisits Mexica tribute as a revenue practice: conquered communities supplied goods and agricultural resources used to support imperial government."], "tea": {"prompt": "Explain one way the Aztec state adapted to its environment.", "topic": "The Aztec used chinampas to support a large lake-based city.", "explain": "They built fertile agricultural plots on shallow lake beds that could produce multiple harvests each year.", "analyze": "The resulting food supply supported Tenochtitlán’s urban population and helped sustain the capital’s political importance."}, "traps": ["Aztec tribute and local rulers contrast with Inca appointed officials and a centralized bureaucracy.", "Chinampas are lake-bed agricultural plots; Inca terraces are mountainside farms. “Floating gardens” is a nickname."], "quiz": {"question": "Which pairing correctly distinguishes the Aztec from the Inca?", "options": ["Aztec: tribute through local rulers; Inca: appointed provincial officials", "Aztec: appointed provincial officials; Inca: independent divine city-kings", "Aztec: mountain terraces; Inca: shallow-lake chinampas", "Aztec: quipu administration; Inca: hieroglyphic writing"], "explanation": "The Americas deck contrasts Aztec indirect tribute rule with centralized Inca administration."}, "displayImage": "assets/web/d4-image7.webp", "units": ["units12", "unit3"]}, {"id": "inca", "name": "Inca Empire", "region": "Americas", "lon": -72.0, "lat": -13.5, "periods": ["core", "earlymodern"], "dates": "Expansion in the 1400s", "image": "assets/slides/d4-image9.jpeg", "refs": ["d4:8", "d4:9", "d4:10", "d9:7", "d9:9"], "summary": "Central administration, labor service, and roads connected the Andes.", "facts": ["The empire divided into four provinces around Cusco. Appointed officials formed a centralized bureaucracy.", "Quipu used knotted strings to record census data, tax obligations, and military organization.", "The mit’a system required male citizens to perform public labor, including farming, road construction, and military service. The state supplied food, clothing, and care in return.", "The Andean road network, bridges, and tunnels supported military movement and communication.", "Terraced farming adapted steep mountainsides for agriculture.", "The slides describe divine authority, polytheism, offerings of goods and llamas, and more limited human sacrifice than in the Aztec example.", "The Unit 3 administration deck adds sacred legitimacy: the Sapa Inca claimed descent from Inti, and the Temple of the Sun at Cuzco reinforced this religious authority."], "tea": {"prompt": "Explain one way the Inca supported centralized rule over difficult terrain.", "topic": "Road infrastructure helped integrate the Andean empire.", "explain": "The Inca built roads, bridges, and tunnels for rapid communication and military movement.", "analyze": "Linking distant provinces made it easier for central authorities to communicate and enforce decisions across mountain terrain."}, "traps": ["Mit’a is a labor obligation; quipu is a record-keeping system.", "Inca central administration differs from Aztec indirect tribute rule and Maya independent city-states."], "quiz": {"question": "What was the function of Inca quipu?", "options": ["Recording information with knotted strings", "Requiring a period of public labor service", "Collecting tribute while retaining local city rulers", "Growing crops on terraces in mountain terrain"], "explanation": "The slides identify quipu as a means of keeping census, tax, and military records."}, "displayImage": "assets/web/d4-image9.webp", "units": ["units12", "unit3"]}, {"id": "maya", "name": "Maya city-states", "region": "Americas", "lon": -88.6, "lat": 20.7, "periods": ["before", "core", "after"], "dates": "Classic 250–900; Postclassic c. 900–1500", "image": "assets/slides/d4-image15.jpeg", "refs": ["d4:3", "d4:11"], "summary": "Shared culture and intellectual traditions without a unified empire.", "facts": ["Maya political organization consisted of competing city-states rather than one unified empire.", "Divine kings ruled individual city-states, which shared culture, religion, and trade connections.", "The slides highlight zero, calendars, and a complex hieroglyphic writing system.", "The end of the Classic period did not mean the disappearance of Maya city-states. The slides discuss the Postclassic period as continuing into the lesson window."], "tea": {"prompt": "Explain one way Maya political organization differed from the Inca.", "topic": "Maya city-states remained politically separate.", "explain": "They shared culture and trade networks, but individual divine kings ruled competing city-states.", "analyze": "Cultural similarities did not create the centralized provincial bureaucracy described in the Inca example."}, "traps": ["The Maya had a writing system; the Inca example uses quipu.", "The Maya Classic period ended before 1200, while Postclassic city-states continued."], "quiz": {"question": "Which statement best describes Maya political organization in the deck?", "options": ["Competing city-states with shared cultural traditions", "A centralized bureaucracy overseeing four provinces", "A three-city alliance centered on Tenochtitlán", "A single state governed through scholar-official examinations"], "explanation": "The Maya slide emphasizes political separation alongside shared culture, religion, and trade."}, "displayImage": "assets/web/d4-image15.webp", "units": ["units12"]}, {"id": "cahokia", "name": "Cahokia", "region": "Americas", "lon": -90.1, "lat": 38.7, "periods": ["before", "core"], "dates": "Peak c. 1050–1200; North American context", "image": "assets/slides/d4-image17.webp", "refs": ["d4:12"], "summary": "A major settlement and trade hub north of Mexico.", "facts": ["The deck describes diverse North American societies, including settled agricultural chiefdoms and nomadic groups.", "Cahokia was a major settlement north of Mexico, with a peak population estimate of 10,000–20,000 in the slides.", "Monks Mound and goods from across the continent illustrate large-scale settlement and long-distance trade.", "The deck uses Cahokia to show that political complexity and trade did not require a large unified empire."], "tea": {"prompt": "Explain how Cahokia challenges the assumption that North American societies lacked complex exchange.", "topic": "Cahokia participated in extensive trade networks.", "explain": "The slide notes the discovery of goods from across the continent at a large settlement with monumental mounds.", "analyze": "These findings support the existence of interregional connections before European contact."}, "traps": ["Absence of a large empire does not imply absence of settlement, hierarchy, or trade.", "Cahokia’s peak is dated c. 1050–1200 in the slides; treat it as context for the main period."], "quiz": {"question": "What evidence does the deck use for Cahokia’s trade connections?", "options": ["Goods from across the continent found there", "Evidence that a single empire ruled all of North America", "A complete absence of agricultural settlements", "A system of trans-Saharan camel caravans"], "explanation": "The North America slide identifies goods from across the continent as evidence of extensive trade."}, "displayImage": "assets/web/d4-image17.webp", "units": ["units12"]}, {"id": "olmec", "name": "Earlier Mesoamerica", "region": "Americas", "lon": -94.6, "lat": 18.1, "periods": ["before"], "dates": "Olmec c. 1200 BCE; Maya Classic 250–900 CE", "image": "assets/slides/d4-image2.jpeg", "refs": ["d4:3", "d4:4"], "summary": "Earlier traditions provide context for later American states.", "facts": ["The deck identifies the Olmec and Classic Maya as earlier Mesoamerican societies.", "These cultures established traditions of governance, religion, and agriculture before 1200 CE.", "Maize became a staple supporting large populations. The map slide also labels Teotihuacan and Toltec as earlier civilizations."], "tea": {"prompt": "Explain one continuity linking earlier and later American societies.", "topic": "Agricultural traditions supported later population growth.", "explain": "The context slide identifies maize cultivation among the foundations laid by earlier cultures.", "analyze": "A sustained food base helped later societies support large populations even as political organizations changed."}, "traps": ["1200 BCE in the Olmec context is different from the main 1200 CE starting point.", "Earlier foundations are context, rather than all examples of states active in 1200–1450."], "quiz": {"question": "Which crop does the Americas context slide identify as a staple?", "options": ["Maize", "Champa rice", "Sugarcane", "Citrus"], "explanation": "The slide explicitly identifies maize, or corn, as a staple supporting American populations."}, "displayImage": "assets/web/d4-image2.webp", "units": ["units12"]}, {"id": "chavin", "name": "Earlier Andes: Chavín", "region": "Americas", "lon": -77.2, "lat": -9.6, "periods": ["before"], "dates": "Chavín c. 900 BCE in the context slide", "image": "assets/slides/d4-image3.webp", "refs": ["d4:3"], "summary": "An earlier Andean society named as background to later states.", "facts": ["The deck identifies Chavín in the Andes as an earlier influence on later civilizations.", "The context slide places Chavín around 900 BCE. It supplies little further state-specific detail.", "Use this example for background continuity, rather than attributing Inca institutions directly to Chavín."], "tea": {"prompt": "Identify an earlier society used as context for Andean state development.", "topic": "Chavín supplies earlier Andean context.", "explain": "The Americas deck names Chavín, around 900 BCE, as an influence on later civilizations.", "analyze": "This places later Andean states within a longer regional history; the slide does not establish identical institutions."}, "traps": ["Chavín is Andean; the Olmec example is Mesoamerican.", "The slide’s Chavín date is BCE, long before the Inca expansion in the 1400s."], "quiz": {"question": "Which earlier society is placed in the Andes in the context slide?", "options": ["Chavín", "Olmec", "Classic Maya", "Cahokia"], "explanation": "The Americas context slide identifies Chavín with the Andes."}, "displayImage": "assets/web/d4-image3.webp", "units": ["units12"]}, {"id": "ghana", "name": "Kingdom of Ghana", "region": "Africa", "lon": -8.0, "lat": 16.5, "periods": ["before"], "dates": "c. 300–1200 CE in the slides", "image": "assets/slides/d5-image2.webp", "refs": ["d5:3"], "summary": "Gold and salt trade provided a foundation for West African state power.", "facts": ["Ghana controlled trans-Saharan gold and salt trade and became wealthy and powerful.", "The slides describe its decline by 1200 as context for Mali’s rise.", "This marker represents the historical kingdom’s approximate region, not the borders of the present-day country."], "tea": {"prompt": "Explain one way trade supported an early West African state.", "topic": "Trans-Saharan commerce supported Ghana’s wealth and power.", "explain": "The kingdom controlled trade in gold and salt.", "analyze": "Control of valuable exchange routes connected economic resources to political strength."}, "traps": ["Ghana precedes Mali in the deck’s sequence.", "The historical kingdom marker does not represent a modern national boundary."], "quiz": {"question": "Which goods does the Ghana context slide emphasize?", "options": ["Gold and salt", "Silk and porcelain", "Rice and timber", "Spices and fine textiles"], "explanation": "The Africa context slide connects Ghana’s wealth to trans-Saharan gold and salt trade."}, "displayImage": "assets/web/d5-image2.webp", "units": ["units12"]}, {"id": "mali", "name": "Mali Empire", "region": "Africa", "lon": -3.0, "lat": 16.8, "periods": ["core", "after"], "dates": "c. 1230–1600; pilgrimage 1324–1325", "image": "assets/slides/d5-image6.jpeg", "refs": ["d5:5", "d5:6", "d5:10"], "summary": "Trans-Saharan trade and Islamic patronage supported imperial authority.", "facts": ["Mali rose after Ghana’s decline. A centralized state managed trade and taxation.", "Trans-Saharan routes carried gold, salt, enslaved people, and ivory between West Africa, North Africa, and the Mediterranean.", "Camel saddles made it possible to carry heavier loads across the desert.", "Mansa Musa’s pilgrimage to Mecca in 1324–1325 displayed wealth and established diplomatic and economic connections.", "Rulers used Islam to legitimize authority. Timbuktu and Gao grew as trading and learning hubs."], "tea": {"prompt": "Explain one way Mansa Musa strengthened Mali’s connections with the Islamic world.", "topic": "Mansa Musa’s pilgrimage linked Mali to wider Islamic networks.", "explain": "His 1324–1325 journey to Mecca demonstrated Mali’s wealth and established diplomatic and economic ties.", "analyze": "The pilgrimage connected religious leadership with political prestige and exchange beyond West Africa."}, "traps": ["Mali depended on trans-Saharan routes; Swahili ports connected to Indian Ocean shipping.", "Mali’s centralized state contrasts with Igbo communal decision-making."], "quiz": {"question": "Which event demonstrated Mali’s wealth and Islamic connections?", "options": ["Mansa Musa’s pilgrimage to Mecca", "Zheng He’s state-funded Indian Ocean expeditions", "Ibn Battuta’s account of travel across Islamic societies", "Marco Polo’s journey to Kublai Khan’s court"], "explanation": "The Africa deck highlights Mansa Musa’s pilgrimage in 1324–1325."}, "displayImage": "assets/web/d5-image6.webp", "units": ["units12"]}, {"id": "swahili", "name": "Swahili city-states", "region": "Africa", "lon": 39.5, "lat": -8.9, "periods": ["core"], "dates": "1200–1450", "image": "assets/slides/d5-image7.png", "refs": ["d5:7", "d5:8"], "summary": "Independent ports connected African goods to Indian Ocean networks.", "facts": ["Kilwa, Mogadishu, Mombasa, and Zanzibar were independent trading ports, rather than one unified empire.", "Ports connected gold, ivory, enslaved people, and timber from the interior to Arabia, Persia, India, and China.", "Islamic governance and local traditions interacted. Stone palaces and mosques expressed wealth and authority.", "The slides use Swahili language, with Bantu and Arabic influences, as an example of cultural blending.", "Arab and Persian merchant diasporas settled in coastal cities, married into local families, and served as intermediaries in trade."], "tea": {"prompt": "Explain how trade encouraged cultural exchange on the Swahili coast.", "topic": "Merchant settlements encouraged cultural blending on the Swahili coast.", "explain": "Arab and Persian traders established communities and family ties, bringing Islam and Arabic influences.", "analyze": "Permanent relationships linked local societies to overseas networks and helped produce syncretic cultural practices."}, "traps": ["Swahili ports were independent city-states, rather than a unified coastal empire.", "A diasporic community is a permanent settlement abroad, not simply a caravan passing through."], "quiz": {"question": "Which example illustrates a merchant diaspora in these slides?", "options": ["Arab and Persian merchants settling in East African ports", "A caravan stopping briefly at a roadside inn", "A messenger changing horses at a Yam station", "An army demanding a city’s surrender"], "explanation": "The diaspora slide describes permanent Arab and Persian merchant settlements and local family ties on the East African coast."}, "displayImage": "assets/web/d5-image7.webp", "units": ["units12"]}, {"id": "zimbabwe", "name": "Great Zimbabwe", "region": "Africa", "lon": 30.9, "lat": -20.3, "periods": ["before", "core"], "dates": "c. 1000–1450", "image": "assets/slides/d5-image9.webp", "refs": ["d5:4", "d5:9"], "summary": "A stone-built inland capital connected gold trade to the coast.", "facts": ["Great Zimbabwe became the capital of a powerful southern African kingdom.", "Large stone walls built without mortar required skilled labor and organized planning. The slides connect them to elite wealth and authority.", "The kingdom controlled routes from the interior to Swahili ports.", "Gold, ivory, and copper moved to the coast and onward through Indian Ocean networks."], "tea": {"prompt": "Explain one way Great Zimbabwe connected to wider trade networks.", "topic": "Great Zimbabwe linked inland resources to maritime exchange.", "explain": "It controlled routes exporting gold, ivory, and copper to Swahili city-states.", "analyze": "Access to coastal intermediaries connected an inland state to Indian Ocean trade and supported its wealth."}, "traps": ["Great Zimbabwe was an inland kingdom, rather than a Swahili coastal port.", "Its connections to Indian Ocean trade ran through coastal trading partners."], "quiz": {"question": "How did Great Zimbabwe participate in Indian Ocean trade?", "options": ["Exporting inland goods through Swahili ports", "Taxing ships directly in the Strait of Malacca", "Relying only on trans-Saharan gold and salt caravans", "Remaining disconnected from coastal exchange"], "explanation": "The deck describes routes connecting the African interior to Swahili ports, which shipped goods across the ocean."}, "displayImage": "assets/web/d5-image9.webp", "units": ["units12"]}, {"id": "ethiopia", "name": "Ethiopia", "region": "Africa", "lon": 39.0, "lat": 12.0, "periods": ["core"], "dates": "1200–1450 study window", "image": "assets/slides/d5-image3.webp", "refs": ["d5:4"], "summary": "A Christian kingdom within Africa’s diverse political landscape.", "facts": ["The slides identify Ethiopia as a centralized Christian kingdom surrounded by Islamic states.", "It provides an example of religious diversity within Africa.", "The deck provides only a brief state-system example, without a detailed Ethiopian chronology."], "tea": {"prompt": "Explain how Ethiopia illustrates religious diversity in Africa.", "topic": "African states did not all share the same religious traditions.", "explain": "The Africa deck identifies Ethiopia as a Christian kingdom alongside Islamic states.", "analyze": "The example limits broad claims that participation in regional networks made all African states Islamic."}, "traps": ["Ethiopia is the Christian kingdom example in this deck.", "The blanket wording in the final Africa slide should be read alongside this explicit exception."], "quiz": {"question": "Which state is identified as a Christian kingdom in the Africa deck?", "options": ["Ethiopia", "Mali", "The Swahili city-states", "The Delhi Sultanate"], "explanation": "The state-systems slide explicitly identifies Ethiopia as Christian."}, "displayImage": "assets/web/d5-image3.webp", "units": ["units12"]}, {"id": "igbo", "name": "Igbo societies", "region": "Africa", "lon": 7.1, "lat": 6.2, "periods": ["core"], "dates": "1200–1450 study window", "image": "assets/slides/d5-image3.webp", "refs": ["d5:4"], "summary": "Kinship and communal decision-making provided decentralized governance.", "facts": ["The slides describe Igbo societies as decentralized, with no kings or emperors in the example.", "Communal decision-making and kinship networks organized governance.", "This provides a contrast to the centralized states of Mali, Ethiopia, and Great Zimbabwe."], "tea": {"prompt": "Explain one difference between Igbo governance and Mali’s state system.", "topic": "Igbo societies used decentralized forms of governance.", "explain": "The slides emphasize communal decisions and kinship networks, while Mali had centralized authority and administration.", "analyze": "Effective political organization could take different forms and did not always require a monarch."}, "traps": ["Decentralized governance does not mean an absence of political organization.", "Do not assign Mali’s emperor and centralized taxation to the Igbo example."], "quiz": {"question": "What organized governance in the Igbo example?", "options": ["Communal decisions and kinship networks", "An emperor supervising centralized trade taxation", "Appointed officials ruling four provinces", "Military lords organized under a shogun"], "explanation": "The Africa deck contrasts Igbo communal decision-making with centralized kingdoms."}, "displayImage": "assets/web/d5-image3.webp", "units": ["units12"]}, {"id": "western-europe", "name": "Western Europe", "region": "Europe", "lon": 2.3, "lat": 48.9, "periods": ["before", "core"], "dates": "1200–1450; earlier Roman and Crusading context", "image": "assets/slides/d6-image5.webp", "refs": ["d6:3", "d6:4", "d6:5", "d6:6", "d6:7"], "summary": "Local political power, manorial labor, and shared Catholic institutions.", "facts": ["Lords and vassals exchanged land, service, and loyalty through feudal obligations. Local nobles limited royal authority.", "Manorialism organized estate production. Serfs owed labor and were bound to the land; the slides distinguish this status from individual sale as slaves.", "The heavy plow and three-field rotation increased agricultural productivity.", "The Catholic Church, the pope, and Latin learning linked Western European societies. Scholasticism combined Christian education with classical learning.", "Gothic architecture reflected Church wealth. Jewish communities contributed through trade and finance while facing persecution, including during the Crusades.", "The Crusades increased contact with the Islamic world, including the movement of ideas, technologies, and goods.", "The Black Death caused labor shortages, bargaining over wages and conditions, and pressures on manorialism and Church authority."], "tea": {"prompt": "Explain one way the Black Death changed European labor relations.", "topic": "Population loss increased surviving workers’ bargaining power.", "explain": "The slides describe labor shortages that allowed workers to seek higher wages and better conditions.", "analyze": "This weakened manorial obligations as some peasants left estates for better opportunities in towns."}, "traps": ["Feudalism concerns political obligations; manorialism concerns estate production and labor.", "Political fragmentation did not eliminate religious unity or all long-distance contacts."], "quiz": {"question": "Which distinction best matches the European deck?", "options": ["Feudalism: political obligations; manorialism: estate economy", "Feudalism: estate labor; manorialism: land-for-service political ties", "Feudalism: examination bureaucracy; manorialism: maritime commerce", "Feudalism: shared religious institutions; manorialism: imperial tribute"], "explanation": "The deck treats land-for-service hierarchies separately from the estate economy and serf labor."}, "displayImage": "assets/web/d6-image5.webp", "units": ["units12"]}, {"id": "england", "name": "England", "region": "Europe", "lon": -0.1, "lat": 51.5, "periods": ["core"], "dates": "Magna Carta example; revolt in 1381", "image": "assets/slides/d6-image3.webp", "refs": ["d6:4", "d6:7"], "summary": "Limits on kings and pressures on feudal hierarchies.", "facts": ["The Magna Carta example illustrates limits on royal power: nobles gained rights and the king was subject to law.", "The English Peasants’ Revolt of 1381 illustrates discontent with feudal hierarchies.", "The slides connect the Black Death and Hundred Years’ War with weakened feudal structures and later centralizing monarchies in England and France."], "tea": {"prompt": "Explain how the Magna Carta illustrates limits on royal authority.", "topic": "English kings faced constraints from nobles and law.", "explain": "The slides state that the Magna Carta granted rights to nobles and placed the king under the law.", "analyze": "This supports the argument that medieval royal power was limited by competing political interests."}, "traps": ["The slide describes rights for nobles; it does not establish modern universal democracy.", "The Black Death’s labor effects and the Magna Carta are different examples of pressures on medieval authority."], "quiz": {"question": "What does the Magna Carta example demonstrate in these slides?", "options": ["Legal and noble limits on royal power", "An end to every form of noble authority", "Universal political rights for every resident", "Royal authority operating above the law"], "explanation": "The Europe deck uses it to show that the king was subject to law and constrained by nobles."}, "displayImage": "assets/web/d6-image3.webp", "units": ["units12"]}, {"id": "byzantium", "name": "Byzantium & Constantinople", "region": "Europe", "lon": 29.0, "lat": 41.0, "periods": ["before", "core"], "dates": "Roman continuity; Great Schism 1054", "image": "assets/slides/d6-image2.webp", "refs": ["d6:3"], "summary": "Eastern Roman continuity and the division of Christianity.", "facts": ["The Byzantine Empire continued Roman traditions in the East, with Constantinople as its capital.", "The Great Schism of 1054 divided the Roman Catholic Church in the West from the Eastern Orthodox Church in the East.", "The Europe deck supplies this as background rather than a detailed Byzantine state study."], "tea": {"prompt": "Explain one religious distinction between Eastern and Western Europe in the slides.", "topic": "The Great Schism divided major Christian institutions.", "explain": "The 1054 split separated Roman Catholic Christianity in the West from Eastern Orthodox Christianity in the East.", "analyze": "Shared Christian origins therefore coexisted with distinct institutions across European regions."}, "traps": ["Roman Catholic corresponds to the West; Eastern Orthodox corresponds to the East.", "The fall of Western Roman authority did not mean all Roman traditions disappeared."], "quiz": {"question": "Which pairing matches the Great Schism slide?", "options": ["West: Roman Catholic; East: Eastern Orthodox", "West: Eastern Orthodox; East: Roman Catholic", "West and East: a single undivided institution after 1054", "West: entirely Islamic; East: entirely Buddhist"], "explanation": "The context slide explicitly identifies the western Catholic and eastern Orthodox traditions."}, "displayImage": "assets/web/d6-image2.webp", "units": ["units12"]}, {"id": "alandalus", "name": "Iberia & al-Andalus", "region": "Europe", "lon": -4.8, "lat": 37.9, "periods": ["core", "after"], "dates": "1200s cultural context; late-1400s extension", "image": "assets/slides/d6-image2.webp", "refs": ["d6:3", "d6:6"], "summary": "Religious interaction and the later Reconquista.", "facts": ["The slides describe Muslims, Christians, and Jews living together in al-Andalus and contributing to art, science, and philosophy.", "They then discuss the Reconquista and the displacement of Muslims and Jews in the late 1400s.", "Treat the late-1400s development as an extension beyond the main 1450 endpoint."], "tea": {"prompt": "Explain how Iberia illustrates change in religious relations.", "topic": "Iberia’s religious relations changed over time.", "explain": "The slides contrast cultural interaction among Muslims, Christians, and Jews with the later Reconquista and displacement.", "analyze": "Religious coexistence in one period should not be assumed to describe every later period."}, "traps": ["The late-1400s example extends beyond the main 1200–1450 study window.", "A description of coexistence should be tied to its time and place."], "quiz": {"question": "Which distinction helps read the Iberian slide accurately?", "options": ["1200s cultural interaction versus later Reconquista developments", "An unchanged religious landscape across all periods", "The complete end of intellectual exchange before 1200", "The same religious institutions as Song China"], "explanation": "The European religion slide contrasts cultural interaction with later changes in the late 1400s."}, "displayImage": "assets/web/d6-image2.webp", "units": ["units12"]}, {"id": "mongols", "name": "Mongol Empire", "region": "Mongol world", "lon": 102.8, "lat": 47.2, "periods": ["core"], "dates": "Unification 1206; four khanates by 1294", "image": "assets/slides/d7-image4.webp", "refs": ["d7:3", "d7:4", "d7:5", "d7:6", "d7:7", "d7:8"], "summary": "Conquest, adapted administration, and far-reaching exchange.", "facts": ["Genghis Khan united Mongol tribes in 1206. The empire later divided into Yuan, Ilkhanate, Golden Horde, and Chagatai khanates.", "Threats and severe violence encouraged surrender. The conquest of Baghdad in 1258 is the slide example.", "Mongol rulers employed foreign officials and adapted local technologies and administrative practices. The slides emphasize religious tolerance alongside submission to the khan.", "The Pax Mongolica supported safer trade. Yam relay stations supplied fresh horses and provisions for communications.", "Marco Polo’s travels to Kublai Khan’s court illustrate long-distance movement under Mongol rule.", "Routes spread gunpowder, paper, printing, religions, and disease. The deck links the Black Death’s westward movement to connected trade routes.", "The slides describe khanate conflict, local rebellions, and declining military advantage before the Ming replaced Yuan in 1368."], "tea": {"prompt": "Explain one way Mongol rule encouraged exchange across Eurasia.", "topic": "Mongol infrastructure supported long-distance communication and trade.", "explain": "The Yam system provided relay stations, fresh horses, and supplies, while secured routes made travel safer.", "analyze": "These connections helped people and knowledge move over long distances, with disease also spreading through the same networks."}, "traps": ["Violent conquest and later support for trade can both describe Mongol rule.", "Yam relay stations supported rapid messages; caravanserai supported merchants and animals."], "quiz": {"question": "What was the Mongol Yam system?", "options": ["Relay stations with fresh horses and supplies", "Roadside inns for merchant caravans and cargoes", "A permanent merchant diaspora in a trading port", "A knotted-string system for census and tax records"], "explanation": "The Mongol deck identifies the Yam as communication infrastructure for rapid travel across the empire."}, "displayImage": "assets/web/d7-image4.webp", "units": ["units12"]}, {"id": "yuan", "name": "Yuan China", "region": "Mongol world", "lon": 116.4, "lat": 39.9, "periods": ["core"], "dates": "Kublai Khan; replaced by Ming in 1368", "image": "assets/slides/d7-image3.png", "refs": ["d7:3", "d7:4", "d7:6", "d7:8", "d1:11"], "summary": "The Chinese khanate in the Song–Yuan–Ming sequence.", "facts": ["The Mongol deck identifies the Yuan Dynasty in China with Kublai Khan.", "Marco Polo is the deck’s example of a traveler who reached Kublai Khan’s court.", "Yuan followed the Song and fell to the Ming in 1368. The Ming restored native Chinese rule while retaining some administrative practices."], "tea": {"prompt": "Explain one political change in China during the lesson period.", "topic": "The Ming replaced Mongol Yuan rule with native Chinese rule.", "explain": "The slides date the fall of Yuan to 1368.", "analyze": "A change in ruling dynasty could coexist with some continuity in administrative practices."}, "traps": ["Song, Mongol Yuan, and Ming are successive dynasties in these decks.", "Zheng He’s state-funded voyages belong to Ming rule, rather than Kublai Khan’s Yuan court."], "quiz": {"question": "Which dynasty replaced Yuan in 1368?", "options": ["Ming", "Song", "The Ilkhanate", "The Golden Horde"], "explanation": "The Mongol and East Asia decks both identify the Ming as the successor to Yuan."}, "displayImage": "assets/web/d7-image3.webp", "units": ["units12"]}, {"id": "ilkhanate", "name": "Ilkhanate", "region": "Mongol world", "lon": 46.3, "lat": 38.1, "periods": ["core"], "dates": "One of four khanates shown in 1294", "image": "assets/slides/d7-image3.png", "refs": ["d7:3", "d7:4", "d7:5"], "summary": "The Persian and Middle Eastern khanate in the Mongol division.", "facts": ["The context slide locates the Ilkhanate in Persia and the Middle East.", "It was one of the four main khanates named in the deck.", "The broader Mongol discussion uses Persian bureaucracy as an example of adapted local administration. The slides provide no separate detailed Ilkhanate chronology."], "tea": {"prompt": "Identify one way Mongol rulers adapted to conquered societies.", "topic": "Mongol rulers adapted local administrative practices.", "explain": "The deck gives Persian bureaucracy as an example of practices used alongside foreign officials.", "analyze": "Adaptation helped rulers administer urban territories beyond their nomadic political background."}, "traps": ["Ilkhanate corresponds to Persia/Middle East; Golden Horde corresponds to Russia/Eastern Europe.", "Khanate labels identify political divisions, rather than separate trade-route names."], "quiz": {"question": "Which region is paired with the Ilkhanate?", "options": ["Persia and the Middle East", "Russia and Eastern Europe", "Central Asia", "China"], "explanation": "The Mongol context slide assigns the Ilkhanate to Persia and the Middle East."}, "displayImage": "assets/web/d7-image3.webp", "units": ["units12"]}, {"id": "golden-horde", "name": "Golden Horde & Russia", "region": "Mongol world", "lon": 47.0, "lat": 48.0, "periods": ["core", "after"], "dates": "Russia/Eastern Europe; tribute ended in 1480 in the deck", "image": "assets/slides/d7-image2.webp", "refs": ["d7:3", "d7:4", "d7:8"], "summary": "Mongol rule in Russia and a later shift toward Moscow.", "facts": ["The slides locate the Golden Horde in Russia and Eastern Europe.", "They describe more than 200 years of rule in Russia and Moscow’s growth as Mongol power weakened.", "Ivan III stopped paying tribute in 1480 in the deck’s account. This belongs after the main 1450 endpoint."], "tea": {"prompt": "Explain one later change in the relationship between Moscow and Mongol rule.", "topic": "Moscow became less subordinate as Mongol power weakened.", "explain": "The deck states that Ivan III stopped paying tribute in 1480.", "analyze": "The end of tribute illustrates a shift in political authority, but its date places it beyond the main study window."}, "traps": ["1480 belongs after 1450; do not use it as an event within 1200–1450.", "Golden Horde is the Russia/Eastern Europe example, distinct from Yuan China."], "quiz": {"question": "Which date in the Mongol deck is a post-1450 extension?", "options": ["Ivan III ending tribute in 1480", "Genghis Khan uniting tribes in 1206", "Baghdad’s conquest in 1258", "Yuan’s replacement in 1368"], "explanation": "The 1480 tribute example is later than the core 1200–1450 window."}, "displayImage": "assets/web/d7-image2.webp", "units": ["units12"]}, {"id": "chagatai", "name": "Chagatai Khanate", "region": "Mongol world", "lon": 79.0, "lat": 43.0, "periods": ["core"], "dates": "One of four khanates shown in 1294", "image": "assets/slides/d7-image3.png", "refs": ["d7:3", "d7:4"], "summary": "The Central Asian khanate named in the Mongol division.", "facts": ["The Mongol deck locates the Chagatai Khanate in Central Asia.", "It appears alongside Yuan China, the Ilkhanate, and the Golden Horde in the four-khanate division.", "The map illustrates its relationship to Eurasian routes. The slides provide limited separate state-specific detail."], "tea": {"prompt": "Identify one political division of the Mongol Empire.", "topic": "Chagatai was one of the Mongol khanates.", "explain": "The context slide names it as the Central Asian division.", "analyze": "The four-khanate example shows that the empire was not a single undivided political unit throughout the period."}, "traps": ["Chagatai corresponds to Central Asia; Yuan corresponds to China.", "The 1294 map shows a political snapshot, rather than unchanging borders for the entire lesson."], "quiz": {"question": "Which khanate is paired with Central Asia?", "options": ["Chagatai", "Yuan", "Golden Horde", "Ilkhanate"], "explanation": "The Mongol context slide directly pairs Chagatai with Central Asia."}, "displayImage": "assets/web/d7-image3.webp", "units": ["units12"]}, {"id": "gunpowder-preview", "name": "Land-based empires · overview", "region": "Islamic world", "lon": 48.0, "lat": 29.0, "periods": ["earlymodern"], "dates": "1450–1750 expansion and administration", "image": "assets/slides/d7-image7.jpeg", "refs": ["d7:8", "d8:3", "d8:4", "d8:13", "d9:3", "d9:11"], "summary": "Military conquest expanded empires; institutions, revenue, and legitimacy sustained them.", "facts": ["Gunpowder weapons spread from China across Eurasia through trade and warfare. Cannons attacked fortifications, while firearms increased military firepower.", "Ottoman, Safavid, Mughal, and Qing rulers expanded through conquest and competition. Leadership, organization, and resources remained essential alongside technology.", "Consolidation concerns strengthening control through officials, institutions, professional forces, and the management of local elites.", "Legitimation concerns convincing people that authority is rightful. Divine claims, art, and monumental architecture could encourage obedience.", "Taxes and tribute provided revenue for governments, armies, and public projects. Different empires used different collection arrangements."], "tea": {"prompt": "Explain one difference between imperial expansion and consolidation.", "topic": "Conquest expanded territory, while administration helped rulers maintain control.", "explain": "The slides pair gunpowder conquest with bureaucracies, professional soldiers, and reliable tax revenue.", "analyze": "Winning territory did not automatically secure obedience or resources; continued rule required institutions and a basis for legitimate authority."}, "traps": ["Gunpowder was an important military factor, but the slides reject technology alone as a complete explanation of imperial success.", "Consolidation strengthens actual control; legitimation supplies claims that authority is rightful. A practice can support both."], "quiz": {"question": "Which practice most directly illustrates legitimation rather than only military expansion?", "options": ["Promoting a divine claim that royal authority comes from God", "Using cannons to breach a fortified city wall", "Deploying cavalry to conquer neighboring territory", "Increasing a firearm-equipped army’s battlefield firepower"], "explanation": "Divine-right claims explain why a ruler’s authority should be regarded as rightful. Cannons and battlefield forces more directly illustrate military expansion."}, "displayImage": "assets/web/d7-image7.webp", "units": ["units12", "unit3"]}, {"id": "ottoman", "name": "Ottoman Empire", "region": "Islamic world", "lon": 28.98, "lat": 41.01, "periods": ["earlymodern"], "units": ["unit3"], "dates": "1453 conquest; Suleiman 1520–1566", "image": "assets/slides/d8-image7.png", "displayImage": "assets/web/d8-image7.webp", "refs": ["d8:8", "d9:5", "d9:4", "d9:8", "d9:10", "d8:9"], "summary": "Military expansion and imperial recruitment supported a centralized state.", "facts": ["Ottoman rulers expanded from Anatolia into southeastern Europe, the Middle East, and North Africa. Mehmed II conquered Constantinople in 1453, using cannons against its defensive walls.", "Suleiman the Magnificent expanded Ottoman power further into Europe and the Middle East. The Ottoman state followed Sunni Islam.", "The devshirme system recruited Christian boys, primarily from the Balkans, converted them to Islam, and trained them for imperial service. Some became administrators; others joined the Janissaries, elite infantry using firearms.", "Training officials and soldiers within imperial institutions strengthened their loyalty to the sultan and reduced dependence on hereditary nobles.", "The millet system allowed recognized religious communities, especially Christians and Jews, to manage many religious and legal affairs while remaining under Ottoman authority. This did not mean equal legal status.", "Tax farmers purchased regional tax-collection rights, paid an agreed amount to the government, and retained additional revenue as profit. This provided revenue without direct imperial management of every taxpayer.", "Ottoman–Safavid rivalry combined territorial competition with an existing Sunni–Shia distinction. Ottoman artillery and firearms contributed to victory at Chaldiran in 1514."], "factRefs": [["d8:8"], ["d8:8"], ["d9:5"], ["d9:4", "d9:5"], ["d9:8"], ["d9:10"], ["d8:9"]], "tea": {"prompt": "Explain one way Ottoman rulers consolidated authority over their empire.", "topic": "Ottoman rulers used imperial recruitment to strengthen central authority.", "explain": "Through devshirme, Christian boys entered an imperial training system that produced administrators and Janissary infantry.", "analyze": "Officials and soldiers trained to serve the sultan gave him support independent of hereditary nobles, reducing his reliance on competing local elites."}, "traps": ["Devshirme was a recruitment system; Janissaries were an elite infantry force. Millet arrangements concerned religious communities; tax farming concerned revenue.", "Ottoman Sunni identity differed from Safavid Twelver Shia identity. Religious toleration under the millet system did not establish equal legal status."], "quiz": {"question": "Which Ottoman practice most directly reduced the sultan’s dependence on hereditary nobles?", "options": ["Training administrators and Janissaries through devshirme", "Allowing religious communities to manage marriage and education", "Selling regional tax-collection rights to tax farmers", "Supporting an official Twelver Shia state religion"], "explanation": "The administration slides connect devshirme training and service to loyalty toward the sultan and reduced reliance on hereditary nobles. Millet institutions and tax farming served other functions."}}, {"id": "safavid", "name": "Safavid Empire", "region": "Islamic world", "lon": 51.67, "lat": 32.65, "periods": ["earlymodern"], "units": ["unit3"], "dates": "Founded in 1501; Chaldiran 1514", "image": "assets/slides/d8-image4.png", "displayImage": "assets/web/d8-image4.webp", "refs": ["d8:9", "d10:6", "d8:4"], "summary": "An official Shia identity intensified rivalry with the neighboring Sunni Ottomans.", "facts": ["Shah Ismail I established Safavid rule in Persia in 1501 through military conquest.", "The Safavids made Twelver Shia Islam their official religion. The slides connect legitimate leadership in Shia tradition to Ali and his descendants.", "Religious differences strengthened political and territorial rivalry with the Sunni Ottomans; both states competed for strategically important Middle Eastern territories.", "At Chaldiran in 1514, Ottoman firearms and artillery contributed to Ottoman victory. The example shows the importance of military organization and access to effective weapons, rather than technology guaranteeing every state’s success."], "factRefs": [["d8:9"], ["d8:9"], ["d8:9", "d10:6"], ["d8:4", "d8:9"]], "tea": {"prompt": "Explain how religion influenced Ottoman–Safavid political rivalry.", "topic": "Religious differences reinforced Ottoman–Safavid competition.", "explain": "The Safavids adopted Twelver Shia Islam while the Ottomans followed Sunni Islam, and the states competed for important territories.", "analyze": "Confessional identity added a religious dimension to existing territorial rivalry; the conflict was shaped by political interests as well as beliefs."}, "traps": ["Safavid Persia was officially Twelver Shia; the Ottoman Empire was Sunni. The distinction predates these empires, while their rivalry intensified it.", "Chaldiran illustrates an Ottoman battlefield victory, not the disappearance of the Safavid state. Avoid reducing all rivalry to religion alone."], "quiz": {"question": "Which statement best explains the Ottoman–Safavid rivalry in the slides?", "options": ["Territorial competition was reinforced by Sunni–Shia religious differences", "Both states adopted the same official religion and ended territorial competition", "The split between Sunni and Shia began for the first time in 1514", "Mughal zamindars governed both states through a shared tax system"], "explanation": "The slides describe both territorial interests and religious differences. They say the rivalry continued after Chaldiran."}}, {"id": "mughal", "name": "Mughal Empire", "region": "South & Southeast Asia", "lon": 78.01, "lat": 27.18, "periods": ["earlymodern"], "units": ["unit3"], "dates": "Babur’s conquests; Akbar’s toleration; 1450–1750", "image": "assets/slides/d9-image8.png", "displayImage": "assets/web/d9-image8.webp", "refs": ["d8:10", "d9:8", "d9:10", "d9:9", "d10:5"], "summary": "Conquest, local tax intermediaries, and religious accommodation sustained imperial rule.", "facts": ["Babur defeated the Delhi Sultanate using artillery, firearms, cavalry, and effective battlefield tactics. Later rulers including Akbar expanded Mughal rule over diverse South Asian populations.", "Akbar promoted religious toleration toward a predominantly Hindu population. In 1564, he abolished the jizya tax and welcomed Hindus into government positions.", "The slides link these policies to greater cooperation and loyalty among religious communities. Toleration was a policy for governing diversity, not the elimination of all religious differences.", "Zamindars were local landholders and elites who collected agricultural taxes, passed revenue to the imperial state, and retained a share. Mughal rulers used established local authorities to collect revenue across a large territory.", "Mughal mosques and mausoleums displayed wealth and artistic achievement. The Taj Mahal is the slide’s monumental architecture example.", "Under Mughal rule, Sikh communities sometimes experienced conflict with imperial authorities. The belief-systems deck connects these tensions to growing Sikh political and military organization."], "factRefs": [["d8:10"], ["d9:8"], ["d9:8"], ["d9:10"], ["d9:9"], ["d10:5"]], "tea": {"prompt": "Explain one way Akbar’s religious policies helped consolidate Mughal rule.", "topic": "Akbar used religious accommodation to encourage cooperation within the Mughal Empire.", "explain": "He abolished the jizya tax in 1564 and admitted Hindus to government positions in a predominantly Hindu society.", "analyze": "Reducing religious barriers and including local communities in government could strengthen loyalty to the empire and make diverse territories easier to govern."}, "traps": ["Mughal zamindars collected agricultural taxes through local authority; Ottoman tax farmers purchased tax-collection rights.", "Akbar abolished jizya in the policy described here. Do not assume every Mughal ruler or every Islamic state followed an identical toleration policy."], "quiz": {"question": "Which distinction between Mughal and Ottoman revenue systems matches the slides?", "options": ["Mughal zamindars were local elites collecting agricultural taxes; Ottoman tax farmers bought collection rights", "Mughal zamindars were infantry recruits; Ottoman tax farmers were religious community leaders", "Mughal rulers required silver taxes in China; Ottoman rulers abolished all taxes on agriculture", "Mughal revenue came only from religious monuments; Ottoman revenue came only from conquered tribute goods"], "explanation": "The taxation slide distinguishes the use of existing Mughal local landholders from the Ottoman sale of regional collection rights."}}, {"id": "qing", "name": "Qing China", "region": "East Asia", "lon": 116.4, "lat": 39.9, "periods": ["earlymodern"], "units": ["unit3"], "dates": "Established at Beijing in 1644; later territorial expansion", "image": "assets/slides/d8-image8.jpeg", "displayImage": "assets/web/d8-image8.webp", "refs": ["d8:11", "d9:9"], "summary": "Manchu conquest, territorial expansion, and imperial representation reshaped Chinese rule.", "facts": ["The Manchus emerged northeast of China with strong cavalry forces and incorporated gunpowder weapons while challenging the declining Ming dynasty.", "Manchu forces entered Beijing in 1644 and established the Qing dynasty. Rulers then consolidated control and expanded into neighboring regions.", "The deck names Qianlong and expansion into Mongolia, Tibet, and Xinjiang. These were developments over time, rather than all territories being acquired in 1644.", "Qing imperial portraits represented emperors as dignified and legitimate rulers, illustrating the use of art to support political authority.", "The map embedded in the Qing slide is explicitly dated circa 1820. It is a later geographic illustration, outside the main 1450–1750 lesson window."], "factRefs": [["d8:11"], ["d8:11"], ["d8:11"], ["d9:9"], ["d8:11"]], "tea": {"prompt": "Explain one change in Chinese political rule during the Unit 3 period.", "topic": "Manchu rulers established Qing rule after challenging the declining Ming state.", "explain": "The slides identify the entry into Beijing in 1644 and the establishment of the Qing dynasty.", "analyze": "The change in ruling dynasty was followed by consolidation and further conquests, so the empire’s later extent should not be treated as its territory at the moment of founding."}, "traps": ["Qing rule began in Beijing in 1644. The slide’s circa-1820 map is not evidence of the empire’s borders in 1644 or throughout 1450–1750.", "The Qing were established by Manchus; the preceding Yuan were Mongol. The Ming silver-tax example is a separate administration case."], "quiz": {"question": "Why should the Qing map in the deck be used carefully for a 1450–1750 question?", "options": ["Its caption dates the depicted extent to about 1820", "Its caption identifies Song China before 1279", "It depicts the Ottoman Empire at Chaldiran", "It shows the founding of Sikhism in northern India"], "explanation": "The date is printed in the map itself. Use the slide’s native text for the 1644 establishment and expansion discussion; the later map does not establish a single Unit 3 border."}, "imageNote": "Source map: circa 1820. It shows a later extent, beyond the main 1450–1750 window."}, {"id": "songhai", "name": "Songhai & Moroccan invasion", "region": "Africa", "lon": -0.05, "lat": 16.27, "periods": ["earlymodern"], "units": ["unit3"], "dates": "Rise after Mali; Tondibi 1591", "image": "assets/slides/d8-image9.webp", "displayImage": "assets/web/d8-image9.webp", "refs": ["d8:12"], "summary": "Trade wealth did not remove vulnerability to a rival with effective gunpowder forces.", "facts": ["As Mali declined in the 1400s, Songhai became a dominant West African power along the Niger River, controlling Gao, Timbuktu, and important trans-Saharan routes.", "Gold and salt trade supported wealth, and Songhai patronized Islamic scholarship.", "Morocco invaded in 1591 to gain access to wealth and trade routes. At Tondibi, Moroccan firearms and artillery helped overcome Songhai’s numerical advantage.", "The defeat weakened central authority and contributed to fragmentation. The example illustrates vulnerability to better-equipped rivals; it does not show that army size alone determined victory."], "factRefs": [["d8:12"], ["d8:12"], ["d8:12"], ["d8:12"]], "tea": {"prompt": "Explain one way military technology affected a West African state.", "topic": "Gunpowder weapons contributed to the weakening of Songhai.", "explain": "At Tondibi in 1591, Moroccan troops used firearms and artillery against Songhai forces relying more on cavalry and traditional weapons.", "analyze": "The defeat weakened central authority and encouraged fragmentation, showing how a technological imbalance could affect an empire’s survival despite numerical strength."}, "traps": ["Tondibi, 1591: Morocco defeated Songhai. Chaldiran, 1514: the Ottomans defeated Safavid forces.", "Songhai inherited important West African trade connections after Mali’s decline. These are successive regional examples, not interchangeable empire names."], "quiz": {"question": "What does the Moroccan victory at Tondibi best illustrate?", "options": ["Effective firearms and artillery could offset an opponent’s numerical advantage", "The largest army invariably defeated the smaller army", "Trade wealth made empires independent of military organization", "Songhai used a devshirme system to recruit Moroccan infantry"], "explanation": "The land-based empires deck connects Morocco’s gunpowder weapons to victory over more numerous Songhai forces and to the weakening of Songhai central authority."}}, {"id": "tokugawa", "name": "Tokugawa Japan", "region": "East Asia", "lon": 139.75, "lat": 35.68, "periods": ["earlymodern"], "units": ["unit3"], "dates": "Shogunate established in 1603", "image": "assets/slides/d9-image5.png", "displayImage": "assets/web/d9-image5.webp", "refs": ["d9:6", "d9:4"], "summary": "A shogun regulated regional lords while samurai increasingly performed administrative work.", "facts": ["The Tokugawa shogunate began in 1603 after generations of civil warfare. The shogun exercised effective political authority while the emperor’s role was more ceremonial.", "Daimyo continued to govern regional domains. The shogunate imposed regulations and obligations to maintain control over them.", "As warfare declined, many samurai became salaried retainers and administrative officials, supporting the authority of the shogun and daimyo.", "The broader administration lesson connects loyal officials and professional service to stronger authority and reduced dependence on powerful local elites."], "factRefs": [["d9:6"], ["d9:6"], ["d9:6"], ["d9:4"]], "tea": {"prompt": "Explain one way Tokugawa rulers maintained political control.", "topic": "The Tokugawa shogunate limited the independence of regional daimyo.", "explain": "The slides describe obligations and regulations imposed on daimyo, alongside the service of samurai as salaried retainers and administrators.", "analyze": "These relationships allowed regional domains to continue while placing their rulers within a political structure supervised by the shogunate."}, "traps": ["Shogun: effective political ruler. Daimyo: regional lord. Samurai: warrior-retainer class, with many entering administrative service.", "The existence of an emperor does not establish that he exercised the effective political authority described in these slides."], "quiz": {"question": "Which change in samurai roles is described for Tokugawa Japan?", "options": ["Many became salaried retainers and administrative officials as warfare declined", "They replaced the shogun with the emperor as the effective political ruler", "They governed all regional domains without obligations to the shogunate", "Their political and administrative service disappeared as military conflict declined"], "explanation": "The administration deck describes a shift in many samurai from battlefield service toward salaried and administrative roles."}}, {"id": "louis-france", "name": "France & Louis XIV", "region": "Europe", "lon": 2.12, "lat": 48.8, "periods": ["earlymodern"], "units": ["unit3"], "dates": "Absolutism and Versailles; 1450–1750 lesson", "image": "assets/slides/d9-image6.png", "displayImage": "assets/web/d9-image6.webp", "refs": ["d9:7", "d9:9"], "summary": "Divine right and the court at Versailles linked royal legitimacy to the management of nobles.", "facts": ["Absolutist rulers sought to concentrate political authority in the monarchy and limit the independence of nobles and other institutions. This describes an aim, not a claim that royal power faced no practical limits.", "Louis XIV promoted divine right: the claim that royal authority came directly from God. This justified stronger royal authority and discouraged challenges.", "Versailles displayed royal wealth through monumental architecture. Court life also helped Louis supervise and influence powerful nobles.", "The slide compares divine-right monarchy with the Sapa Inca’s claimed descent from Inti. Different religious traditions could serve a similar legitimizing function."], "factRefs": [["d9:7"], ["d9:7"], ["d9:9"], ["d9:7"]], "tea": {"prompt": "Explain how Versailles helped Louis XIV strengthen royal authority.", "topic": "Versailles supported royal authority through both display and court politics.", "explain": "Its elaborate architecture showed wealth, while court life let Louis XIV supervise and influence powerful nobles.", "analyze": "The palace made monarchy visibly prestigious and gave the king a setting for managing elite behavior, linking cultural patronage to political consolidation."}, "traps": ["Legitimation explains why subjects should regard rule as rightful; consolidation concerns the institutions and practices that strengthen actual control.", "Divine right in France and sacred ancestry in the Inca example supported legitimacy through different religious traditions. Do not treat them as the same religion."], "quiz": {"question": "Which interpretation of Versailles is best supported by the administration slide?", "options": ["It displayed royal wealth and helped the king supervise influential nobles", "It was only a military fort with no ceremonial role", "It replaced French monarchy with independent daimyo domains", "It established the Protestant doctrine of faith alone"], "explanation": "The slide explicitly identifies both architectural display and the political function of court life."}}, {"id": "ming-silver", "name": "Ming China · silver taxes", "region": "East Asia", "lon": 118.8, "lat": 32.06, "periods": ["earlymodern"], "units": ["unit3"], "dates": "Ming taxation in the 1450–1750 lesson", "image": "assets/slides/d9-image9.jpeg", "displayImage": "assets/web/d9-image9.webp", "refs": ["d9:10", "d1:11"], "summary": "Changes in tax payments connected state revenue to wider silver trade.", "facts": ["The Ming government increasingly required taxes in silver instead of goods or labor.", "The slides connect silver payments to simpler taxation and increased demand for silver.", "This demand linked China’s economy more closely to expanding global trade networks.", "This entry focuses on the later taxation example. Zheng He’s 1405–1433 voyages remain in the earlier Ming entry under Units 1–2."], "factRefs": [["d9:10"], ["d9:10"], ["d9:10"], ["d1:11", "d9:10"]], "tea": {"prompt": "Explain one way Ming taxation affected economic connections.", "topic": "Ming tax requirements increased China’s demand for silver.", "explain": "The government increasingly required payment in silver rather than goods or labor.", "analyze": "Tax obligations created demand for a commodity moving through global trade, linking the state’s revenue system with broader economic networks."}, "traps": ["Ming China: taxes increasingly paid in silver. Ottoman tax farming: purchased collection rights. Mughal zamindars: local elites collecting agricultural revenue.", "Zheng He’s voyages occurred in 1405–1433. Keep that earlier diplomatic example distinct from the later Unit 3 taxation discussion."], "quiz": {"question": "What economic connection does the slide draw from Ming silver-tax requirements?", "options": ["Tax obligations increased silver demand and strengthened links with global trade", "Silver taxes removed China from all international commerce", "Ming taxes became a levy recruiting Christian boys for infantry", "Silver payments were the same practice as Inca labor service"], "explanation": "The taxation slide connects the shift to silver payment with greater silver demand and wider trade integration."}}, {"id": "protestant", "name": "Protestant Reformation", "region": "Europe", "lon": 12.65, "lat": 51.87, "periods": ["earlymodern"], "units": ["unit3"], "dates": "Luther’s Ninety-Five Theses, 1517", "image": "assets/slides/d10-image2.png", "displayImage": "assets/web/d10-image2.webp", "refs": ["d10:3", "d6:3"], "summary": "Religious criticism, printing, and rulers’ political interests challenged Catholic authority.", "facts": ["Criticism of Church corruption and practices, including the sale of indulgences associated with reducing punishment for sins, challenged Catholic authority.", "In 1517, Martin Luther published the Ninety-Five Theses criticizing indulgence sales. He taught salvation through faith alone and treated the Bible, rather than the pope, as the highest religious authority.", "The printing press helped his ideas spread rapidly. Lutheranism and Calvinism challenged Catholic authority as new Protestant denominations.", "Some rulers supported Protestant movements to gain independence from the Catholic Church. Religious change interacted with political interests.", "The Reformation divided Western Christianity and contributed to religious and political conflicts. This is different from the earlier Catholic–Orthodox Schism of 1054."], "factRefs": [["d10:3"], ["d10:3"], ["d10:3"], ["d10:3"], ["d10:3", "d6:3"]], "tea": {"prompt": "Explain one way technology contributed to religious change in Europe.", "topic": "Printing helped Protestant ideas reach a larger audience.", "explain": "The slides describe the rapid spread of Luther’s criticisms and teachings through the printing press.", "analyze": "Wider circulation gave religious challenges reach beyond their original location, allowing more people and rulers to encounter alternatives to Catholic authority."}, "traps": ["Luther emphasized faith alone and biblical authority. The Council of Trent reaffirmed Catholic institutional authority and faith with good works.", "The 1517 Protestant challenge differs from the 1054 Catholic–Orthodox division. Match each religious change to its period and institutions."], "quiz": {"question": "Which pairing correctly distinguishes Luther’s teachings from the Council of Trent?", "options": ["Luther: faith alone and biblical authority; Trent: faith and good works with Church authority", "Luther: Church authority and faith with good works; Trent: faith alone and rejection of papal authority", "Both rejected the authority of the Catholic Church and adopted the same doctrine of salvation", "Both defined the purchase of indulgences as the highest source of religious authority"], "explanation": "The belief-systems slides distinguish Protestant challenges from the Catholic response without presenting the Council as accepting Luther’s doctrine."}}, {"id": "catholic-reform", "name": "Catholic Counter-Reformation", "region": "Europe", "lon": 11.12, "lat": 46.07, "periods": ["earlymodern"], "units": ["unit3"], "dates": "Council of Trent, 1545–1563", "image": "assets/slides/d6-image5.webp", "displayImage": "assets/web/d6-image5.webp", "refs": ["d10:4", "d6:6"], "summary": "Institutional reform, reaffirmed doctrine, education, and missions sustained Catholic Christianity.", "facts": ["The Catholic Reformation responded to Protestant challenges by correcting abuses, strengthening discipline, and reaffirming Catholic doctrine.", "At the Council of Trent, 1545–1563, leaders reaffirmed Church authority, faith and good works, and traditional teachings. Reforms also addressed priests’ education and conduct.", "Jesuits established schools and sent missionaries around the world. The slides connect Catholic missions with expansion into parts of Asia.", "Spanish and Portuguese colonial expansion contributed to the spread of Christianity in the Americas. Both Catholic and Protestant movements participated in Christianity’s continued expansion."], "factRefs": [["d10:4"], ["d10:4"], ["d10:4"], ["d10:4"]], "tea": {"prompt": "Explain one way the Catholic Church responded to the Protestant Reformation.", "topic": "The Catholic Church strengthened institutions while reaffirming its teachings.", "explain": "The Council of Trent reaffirmed Church authority and faith with good works, while reforms improved priestly education and conduct.", "analyze": "Responding to abuses and reinforcing doctrine helped the Church defend its authority without adopting the central Protestant teachings it opposed."}, "traps": ["Counter-Reformation means a Catholic response including reform and doctrinal reaffirmation, rather than conversion of the Church to Lutheranism.", "Jesuits were a Catholic religious order engaged in education and missions; they were not a Protestant denomination."], "quiz": {"question": "Which activity matches the Catholic response described in the slides?", "options": ["Jesuit schools and missions, alongside doctrinal reaffirmation at Trent", "The Council of Trent declaring the pope no longer held authority", "Jesuits founding Lutheran and Calvinist denominations", "The Catholic Church ending all missionary activity after 1517"], "explanation": "The slide links the Council’s doctrinal reaffirmation with educational reform and expanding Catholic missions."}, "imageNote": "Church illustration from the earlier Europe deck. The Unit 3 notes come from the Counter-Reformation slide."}, {"id": "sikhism", "name": "Sikhism & Amritsar", "region": "South & Southeast Asia", "lon": 74.88, "lat": 31.62, "periods": ["earlymodern"], "units": ["unit3"], "dates": "Guru Nanak; late 1400s onward", "image": "assets/slides/d10-image3.png", "displayImage": "assets/web/d10-image3.webp", "refs": ["d10:5"], "summary": "A distinct religious community emerged amid interaction and later tensions in South Asia.", "facts": ["Guru Nanak founded Sikhism in northern India in the late fifteenth century, in a society shaped by longstanding Hindu–Muslim interaction.", "Sikhism developed as a distinct religious tradition. The slides identify belief in one God, spiritual equality, honest work, service, and devotion.", "Sikh teachings challenged caste discrimination and emphasized a direct relationship with God.", "Successive gurus organized and expanded the community. Conflict with some Mughal authorities contributed to growing political and military organization.", "The Golden Temple at Amritsar became a major religious center and is the image used in the deck."], "factRefs": [["d10:5"], ["d10:5"], ["d10:5"], ["d10:5"], ["d10:5"]], "tea": {"prompt": "Explain one way cultural interactions influenced religious development in South Asia.", "topic": "Hindu–Muslim interaction formed part of the setting in which Sikhism emerged.", "explain": "Guru Nanak founded a distinct tradition emphasizing one God, spiritual equality, service, and opposition to caste discrimination.", "analyze": "The example shows how interaction could provide a setting for new religious communities with their own teachings, rather than simply reproducing an existing faith."}, "traps": ["Sikhism is a distinct religious tradition; the slides do not describe it as merely a denomination of Hinduism or Islam.", "Religious interaction could accompany the emergence of a new community, while later political conflicts affected its organization. These are connected but different developments."], "quiz": {"question": "Which description of Sikhism best matches the belief-systems deck?", "options": ["A distinct tradition founded by Guru Nanak that emphasized one God and spiritual equality", "A Catholic missionary order established by the Council of Trent", "The official Twelver Shia identity of Safavid Persia", "A Mughal tax-collection system run by local landholders"], "explanation": "The slide treats Sikhism as a distinct tradition that emerged in the context of Hindu–Muslim interaction and challenged caste discrimination."}}], "issues": [{"refs": ["d2:8"], "title": "Invention versus preservation and transmission", "text": "This slide attributes the invention of the astrolabe and the numeral system to Islamic scholars. These origin claims need a teacher check. Study notes use the supported discussion of translation, scholarship, and algebra instead."}, {"refs": ["d5:10", "d5:4"], "title": "Avoid a blanket claim about Africa", "text": "The final slide says Africa was fully integrated into Dar al-Islam. Slide 4 explicitly identifies Christian Ethiopia. Use specific states and networks rather than assuming that all African societies were Islamic."}, {"refs": ["d6:4", "d2:4"], "title": "Dar al-Islam was politically diverse", "text": "The Europe slide groups Dar al-Islam with centralized empires, while the Islamic-world deck emphasizes political fragmentation. Distinguish particular centralized states from the wider cultural region."}, {"refs": ["d3:12"], "title": "Ship design wording needs a check", "text": "The slide groups dhows and junks together with lateen sails. The guide uses the narrower point that ship technology and monsoon knowledge supported maritime trade, without generalizing one sail design to both."}, {"refs": ["d4:13", "d6:8"], "title": "Treat absolute isolation claims carefully", "text": "These summaries use broad isolation language. The Europe deck itself describes Crusading and Islamic-world contacts. Use the specific connections supported by the slides, and ask your teacher before relying on absolute claims about no contact."}, {"id": "qing-map-period", "refs": ["d8:11"], "title": "Qing map is later than the lesson window", "text": "The embedded map is captioned circa 1820. It should not be read as the Qing extent in 1644 or as a map for the whole 1450–1750 period. The study entry labels the later map explicitly."}, {"id": "mughal-map-dates", "refs": ["d8:7", "d8:10"], "title": "Two different first dates on the Mughal map", "text": "The map title begins at 1526, but its Babur legend says 1525. The native text describes Babur’s conquest without specifying a date. Study notes therefore do not use the conflicting legend as a precise founding date."}], "meta": {"decks": 10, "slides": 105, "images": 100, "scope": "The supplied classroom decks cover Units 1–2 around 1200–1450 and Unit 3 around 1450–1750, with earlier context and some later illustrations. This is not a complete AP World History course.", "method": "Historical notes paraphrase the supplied classroom slides. TEA models, MCQ distinctions, comparisons, and quiz questions are study aids derived from that evidence, not official exam questions. Pins are approximate geographic anchors, not historical borders. Unit and period tags describe the material discussed; they do not establish continuous rule for a whole window.", "unit3Slides": 30}};